infix fun ShortColumn.gt(value: Short): Where = Where("`$name` > ?", listOf { s, i -> s.bindLong(i, value.toLong()) })
infix fun ShortColumn.lt(value: Short): Where = Where("`$name` < ?", listOf { s, i -> s.bindLong(i, value.toLong()) })

class ByteColumn(name: String) : ColumnRef(name)
infix fun ByteColumn.eq(value: Byte): Where = Where("`$name` = ?", listOf { s, i -> s.bindLong(i, value.toLong()) })

class DoubleColumn(name: String) : ColumnRef(name)
infix fun DoubleColumn.eq(value: Double): Where = Where("`$name` = ?", listOf { s, i -> s.bindDouble(i, value) })
infix fun DoubleColumn.neq(value: Double): Where = Where("`$name` != ?", listOf { s, i -> s.bindDouble(i, value) })
infix fun DoubleColumn.gt(value: Double): Where = Where("`$name` > ?", listOf { s, i -> s.bindDouble(i, value) })
infix fun DoubleColumn.gte(value: Double): Where = Where("`$name` >= ?", listOf { s, i -> s.bindDouble(i, value) })
infix fun DoubleColumn.lt(value: Double): Where = Where("`$name` < ?", listOf { s, i -> s.bindDouble(i, value) })
infix fun DoubleColumn.lte(value: Double): Where = Where("`$name` <= ?", listOf { s, i -> s.bindDouble(i, value) })
infix fun DoubleColumn.between(range: ClosedRange<Double>): Where =
    Where("`$name` BETWEEN ? AND ?", listOf({ s, i -> s.bindDouble(i, range.start) }, { s, i -> s.bindDouble(i, range.endInclusive) }))

class FloatColumn(name: String) : ColumnRef(name)
infix fun FloatColumn.eq(value: Float): Where = Where("`$name` = ?", listOf { s, i -> s.bindFloat(i, value) })
infix fun FloatColumn.gt(value: Float): Where = Where("`$name` > ?", listOf { s, i -> s.bindFloat(i, value) })
infix fun FloatColumn.lt(value: Float): Where = Where("`$name` < ?", listOf { s, i -> s.bindFloat(i, value) })

class BooleanColumn(name: String) : ColumnRef(name)
infix fun BooleanColumn.eq(value: Boolean): Where =
    Where("`$name` = ?", listOf { s, i -> s.bindBoolean(i, value) })

class ByteArrayColumn(name: String) : ColumnRef(name)
infix fun ByteArrayColumn.eq(value: ByteArray): Where =
    Where("`$name` = ?", listOf { s, i -> s.bindBlob(i, value) })
